import{HUB,townState,inHubRegion}from'./hub-registration.mjs';
const authorities=new WeakMap(),grants=new WeakMap();
const fields=['sceneId','mapId','revision','state','imageSHA','maskSHA','pinsVerified','phase','foot','facing','sessionEpoch'];
function record(x,keys){if(!x||Object.getPrototypeOf(x)!==Object.prototype||Reflect.ownKeys(x).length!==keys.length)return null;const out={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(x,k);if(!d||!d.enumerable||!Object.hasOwn(d,'value'))return null;out[k]=d.value}return out}
function exact(a,b){if(b===null||typeof b!=='object')return a===b;if(!a||typeof a!=='object'||Array.isArray(a)!==Array.isArray(b)||Reflect.ownKeys(a).length!==Reflect.ownKeys(b).length)return false;return Reflect.ownKeys(b).every(k=>{const d=Object.getOwnPropertyDescriptor(a,k);return d&&Object.hasOwn(d,'value')&&exact(d.value,b[k])})}
export function createS5EntryAuthority({readNative,getWorld}={}){if(typeof readNative!=='function'||typeof getWorld!=='function')throw Error('S5_ENTRY_READER_REQUIRED');const a=Object.freeze({});authorities.set(a,{readNative,getWorld});return a}
export const isS5EntryAuthority=a=>authorities.has(a);
export const isS5EntryRequest=(id,a)=>id===HUB.pointId&&record(a,['type'])?.type==='warp';
function read(a,w,id){const binding=authorities.get(a),fn=binding?.readNative;if(!fn||binding.getWorld()!==w||id!==HUB.pointId||!exact(w.definition.points[id],HUB.sourceRow))return null;const s=w.snapshot();if(s.position.scene!==HUB.mapId||s.world.mapId!==HUB.mapId)return null;const n=record(fn(),fields),state=townState(s,w.story.contract,w.definition),pin=HUB.states[state];if(!n||n.sceneId!==HUB.sceneId||n.mapId!==HUB.mapId||n.revision!==HUB.revision||n.state!==state||n.imageSHA!==pin.imageSHA||n.maskSHA!==pin.maskSHA||n.pinsVerified!==true||n.phase!=='field'||n.facing!=='up'||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<0)return null;if(!Array.isArray(n.foot)||Reflect.ownKeys(n.foot).length!==3||n.foot.length!==2||![0,1].every(i=>{const d=Object.getOwnPropertyDescriptor(n.foot,String(i));return d&&d.enumerable&&Object.hasOwn(d,'value')&&Number.isInteger(d.value)}))return null;if(!inHubRegion(n.foot,state))return null;return n.sessionEpoch}
export function mintS5EntryGrant(a,w,id){const epoch=read(a,w,id);if(epoch===null)throw Error('S5_ENTRY_AUTHORITY_REJECTED');const g=Object.freeze({});grants.set(g,{a,w,id,epoch});return g}
export function validateS5EntryGrant(g,w,s,id){const p=grants.get(g);return!!p&&p.w===w&&p.id===id&&s.position.scene===HUB.mapId&&s.world.mapId===HUB.mapId&&read(p.a,w,id)===p.epoch}
export const revokeS5EntryGrant=g=>grants.delete(g);
